// Borg Agent CPU-port tests: build the Grail compiler, compile each test program under borg/tests
// with the port sources as modules, run it over its fixture set, and diff its output against the
// committed reference in borg/tests/parity.
//
//   bun tools/borg-test.mjs                 hermetic: compare against the committed reference
//   bun tools/borg-test.mjs --regenerate    rebuild the reference from Borg's own serde_json
//
// The reference is generated by a Rust program that parses the same bytes with serde_json 1.0.151
// and `arbitrary_precision` — the crate version and feature set crates/borg-* build with — so the
// port is compared against Borg's JSON semantics rather than a transcription of them.
import { mkdirSync, readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import { join, basename } from 'node:path';
import { buildCompiler, command, compileProgram, execute, root } from './native.mjs';

// `--anchors` re-checks that the rules the session reference carries verbatim still exist in the
// Borg checkout. It is opt-in because the default suite must run without one.
if (process.argv.includes('--anchors')) {
  const agentRoot = process.env.BORG_AGENT_ROOT ?? '/home/shulgin/agent';
  const manifest = JSON.parse(readFileSync(join(root, 'borg/tests/parity/anchors.json'), 'utf8'));
  const sources = new Map();
  const read = (file) => {
    if (!sources.has(file)) sources.set(file, readFileSync(join(agentRoot, file), 'utf8'));
    return sources.get(file);
  };
  let missing = 0;
  for (const anchor of manifest.anchors) {
    if (read(anchor.source).includes(anchor.snippet)) {
      console.log(`anchor ok      ${anchor.what}`);
    } else {
      missing += 1;
      console.error(`anchor MISSING ${anchor.what}: ${anchor.source} no longer contains ${JSON.stringify(anchor.snippet)}`);
    }
  }
  if (missing > 0) {
    console.error(`\n${missing} anchor(s) missing: the ported rule has drifted from ${manifest.source}`);
    process.exit(1);
  }
  const files = [...sources.keys()].join(', ');
  console.log(`\n${manifest.anchors.length} anchors match ${files}`);
  process.exit(0);
}

const regenerate = process.argv.includes('--regenerate');
const suiteDirectory = join(root, 'borg/tests');
const parityDirectory = join(suiteDirectory, 'parity');
const referenceDirectory = join(parityDirectory, 'ref');
const work = join(root, '.work/borg');
mkdirSync(work, { recursive: true });

// Modules every port test links: the port sources plus the standard-library modules they import.
const portSources = readdirSync(join(root, 'borg/src')).filter(f => f.endsWith('.grl')).map(f => `borg/src/${f}`);
const stdModules = ['lib/core.grl', 'lib/strings.grl', 'lib/vecs.grl', 'lib/order.grl', 'lib/hash.grl',
                    'lib/io.grl', 'lib/fs.grl', 'lib/env.grl'];

// Each test names its fixture directories; both sides receive the same sorted file list on argv.
const fixtures = {
  json: ['borg/tests/fixtures/v1', 'borg/tests/fixtures/edge'],
  wire: ['borg/tests/fixtures/v1', 'borg/tests/fixtures/wire'],
  toml: ['borg/tests/fixtures/toml/configs', 'borg/tests/fixtures/toml/cases', 'borg/tests/fixtures/toml/cases/invalid'],
  config: ['borg/tests/fixtures/config'],
  session: ['borg/tests/fixtures/session'],
  jsonrpc: ['borg/tests/fixtures/jsonrpc'],
  supervisor: ['borg/tests/fixtures/supervisor'],
};

function fixturePaths(name) {
  const directories = fixtures[name];
  if (!directories) throw new Error(`no fixture set for ${name}; add it to tools/borg-test.mjs`);
  const paths = [];
  for (const directory of directories) {
    for (const file of readdirSync(join(root, directory)).sort()) {
      if (file.endsWith('.json') || file.endsWith('.toml')) paths.push(join(root, directory, file));
    }
  }
  return paths;
}

// Crates that must not share a feature graph with the shared reference (see ref-acp/Cargo.toml).
const referenceManifests = { jsonrpc: join(root, 'borg/tests/parity/ref-acp/Cargo.toml') };

function referenceBinary(name) {
  const manifest = referenceManifests[name] ?? join(referenceDirectory, 'Cargo.toml');
  if (!existsSync(manifest)) throw new Error(`missing reference crate: ${manifest}`);
  command(['cargo', 'build', '--offline', '--quiet', '--manifest-path', manifest, '--bin', name]);
  const binary = join(manifest, '..', 'target', 'debug', name);
  if (!existsSync(binary)) throw new Error(`reference binary not built: ${binary}`);
  return binary;
}

function regenerateReference(name) {
  const result = execute(referenceBinary(name), fixturePaths(name));
  if (result.status !== 0) throw new Error(`${name}: reference generator failed (${result.status})`);
  const output = result.stdout.toString();
  writeFileSync(join(parityDirectory, `${name}.txt`), output);
  return output;
}

const tests = readdirSync(suiteDirectory).filter(f => f.endsWith('_test.grl')).sort();
if (tests.length === 0) throw new Error('borg/tests has no *_test.grl programs');

const compiler = buildCompiler();
let failures = 0;
for (const test of tests) {
  const name = basename(test, '_test.grl');
  const expectedPath = join(parityDirectory, `${name}.txt`);
  const expected = regenerate ? regenerateReference(name) : readFileSync(expectedPath, 'utf8');
  const paths = fixturePaths(name);
  const executable = compileProgram(compiler, [`borg/tests/${test}`, ...portSources, ...stdModules],
    join(work, name), { name, typedRefs: true });
  const result = execute(executable, paths);
  if (result.status !== 0) {
    failures += 1;
    console.error(`${test}: exit ${result.status}${result.stderr?.trim() ? `\n${result.stderr.trim()}` : ''}`);
    continue;
  }
  const actual = result.stdout.toString();
  if (actual === expected) {
    console.log(`${test}: ${expected.trimEnd().split('\n').length} reference lines match (${paths.length} documents)`);
    continue;
  }
  failures += 1;
  const want = expected.trimEnd().split('\n');
  const got = actual.trimEnd().split('\n');
  const width = Math.max(want.length, got.length);
  console.error(`${test}: output differs from ${expectedPath}`);
  let shown = 0;
  for (let i = 0; i < width; i++) {
    if (want[i] === got[i]) continue;
    console.error(`  line ${i + 1}\n    reference: ${want[i] ?? '(missing)'}\n    grail:     ${got[i] ?? '(missing)'}`);
    shown += 1;
    if (shown === 10) {
      console.error('  (further differences omitted)');
      break;
    }
  }
}
if (failures > 0) {
  console.error(`\n${failures} test program(s) failed`);
  process.exit(1);
}
console.log(`\n${tests.length} test program(s) passed`);
